-- ============================= RESUMEN =============================
SELECT
  'person'             AS tabla, COUNT(*) FILTER (WHERE created_by='Seeds') AS registros FROM public.person             WHERE created_by='Seeds'
UNION ALL SELECT 'patient',          COUNT(*) FROM public.patient          WHERE created_by='Seeds'
UNION ALL SELECT 'patient_responsible',COUNT(*) FROM public.patient_responsible WHERE created_by='Seeds'
UNION ALL SELECT 'appointment',      COUNT(*) FROM public.appointment      WHERE created_by='Seeds'
UNION ALL SELECT 'form_response',    COUNT(*) FROM public.form_response    WHERE created_by='Seeds'
UNION ALL SELECT 'contract',         COUNT(*) FROM public.contract         WHERE created_by='Seeds'
UNION ALL SELECT 'payment_manager',  COUNT(*) FROM public.payment_manager  WHERE created_by='Seeds'
UNION ALL SELECT 'pretreatment_exam',COUNT(*) FROM public.pretreatment_exam WHERE created_by='Seeds'  -- ~96 piezas revisadas
UNION ALL SELECT 'treatment_progress',COUNT(*) FROM public.treatment_progress WHERE created_by='Seeds'  -- ~48 pagos parciales
UNION ALL SELECT 'monitoring',        COUNT(*) FROM public.monitoring        WHERE created_by='Seeds';  -- 60 seguimientos
